    # stopping at other non-background cells and never overwriting them.
    for color in {v for row in grid for v in row if v != background}:
        pts = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color}
        for r, c in pts:
            for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                nr, nc = r + dr, c + dc
                if (nr, nc) not in pts:
                    continue
                # Extend outward from each end of a diagonal pair.
                for sr, sc in ((-dr, -dc), (dr, dc)):
                    rr, cc = (r, c) if (sr, sc) == (-dr, -dc) else (nr, nc)
                    rr += sr
                    cc += sc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
