    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)
    colors = set(freq) - {bg}
    for color in colors:
        pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == color]
        # Line extension from two or more collinear diagonal points.
        if len(pts) < 2:
            continue
        pts.sort()
        # Find a unit diagonal direction represented by a pair.
        dirs = []
        for i,(r1,c1) in enumerate(pts):
            for r2,c2 in pts[i+1:]:
                dr,dc=r2-r1,c2-c1
                if dr and abs(dr)==abs(dc):
                    step=(1 if dr>0 else -1, 1 if dc>0 else -1)
                    dirs.append(step)
        if not dirs:
            continue
        # Pair belonging to longest repeated run; use its ends to extend.
        dr,dc=dirs[0]
        for r,c in pts:
            for sr,sc in ((dr,dc),(-dr,-dc)):
