 "content": "def transform(grid):
    """Extend the two diagonal marker lines in an ARC grid."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Each repeated diagonal pair defines a line. Extend its direction on both
    # sides to the grid edge, leaving all originally occupied cells unchanged.
    for color in counts:
        if color == background:
            continue
        points = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color}
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in points:
                if (r-dr, c-dc) in points:
                    continue
                run = []
                rr, cc = r, c
                while (rr, cc) in points:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for rr, cc, sr, sc in ((run[0][0]-dr, run[0][1]-dc, -dr, -dc),
                                       (run[-1][0]+dr, run[-1][1]+dc, dr, dc)):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out

