 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(x == v for row in grid for x in row))
    for color in colors - {bg}:
        points = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color}
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in points:
                nr, nc = r + dr, c + dc
                if (nr, nc) not in points:
                    continue
                # The adjacent pair determines the diagonal line; extend outward
                # until the boundary or another original colored cell.
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= dr
                    cc -= dc
                rr, cc = nr + dr, nc + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
