 "content": "def transform(grid):
    """Extend diagonal rays of repeated marker colors through the background."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Every repeated diagonal pair defines a ray. Extend both ends until the
    # canvas edge or another original non-background cell.
    for color in counts:
        if color == background:
            continue
        points = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color}
        for r, c in points:
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    out[rr][cc] = color
                    rr -= dr
                    cc -= dc
                rr, cc = nr + dr, nc + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out

